window.addEventListener('load', function(){
  if(!window.gsap || !window.ScrollTrigger) return;
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  gsap.registerPlugin(ScrollTrigger);
  // NOTE: never animate the hero visual's OPACITY here. rAF throttles in
  // background tabs and can freeze an opacity tween mid-flight, leaving the
  // dashboard washed-out. Animate a gentle slide only; the visual is always
  // fully opaque and readable even if a tween is interrupted.
  var vis = document.querySelector('.ihero__visual');
  var viz = document.querySelector('.ihero__viz');
  if(viz){
    gsap.from(viz, {y:24, duration:.8, ease:'power3.out', clearProps:'transform'});
  }
  if(vis){
    gsap.to(vis, {yPercent:-5, ease:'none', scrollTrigger:{trigger:vis, start:'top 80%', end:'bottom top', scrub:0.6}});
  }
});

// Dynamic blog list from Google Sheet (CSV)
document.addEventListener('DOMContentLoaded', function () {
  var grid = document.getElementById('csGrid');
  if (!grid || grid.getAttribute('data-loaded')) return;
  grid.setAttribute('data-loaded', '1');

  var countEl = document.getElementById('csCount');
  var emptyEl = document.getElementById('csEmpty');
  var sentinel = document.getElementById('csSentinel');

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function cardHtml(b) {
    var href = '/blogs/' + encodeURIComponent(b.slug) + '/';
    return '<a class="cs-card cs-reveal" href="' + href + '">' +
      '<div class="cs-card__top"><span class="cs-tag">' + esc(b.category) + '</span></div>' +
      '<h3>' + esc(b.title) + '</h3>' +
      '<p>' + esc(b.description) + '</p>' +
      '<span class="cs-readmore">Read Blog ' +
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
      '<path d="M5 12h14" /><path d="m12 5 7 7-7 7" /></svg></span></a>';
  }

  function showEmpty() {
    grid.innerHTML = '';
    if (emptyEl) emptyEl.hidden = false;
    if (countEl) countEl.textContent = '';
  }

  window.WebstrailBlogs.load()
    .then(function (blogs) {
      if (!blogs.length) return showEmpty();

      grid.innerHTML = blogs.map(cardHtml).join('');
      var cards = Array.prototype.slice.call(grid.querySelectorAll('.cs-card'));

      // lazy infinite-scroll reveal, same behaviour as /blog
      var BATCH = 6, shown = 0, io = null;
      function updateCount() { if (countEl) countEl.textContent = 'Showing ' + shown + ' of ' + cards.length + ' blogs'; }
      function reveal() {
        var end = Math.min(shown + BATCH, cards.length);
        for (var i = shown; i < end; i++) {
          (function (card) { card.hidden = false; requestAnimationFrame(function () { card.classList.add('cs-in'); }); })(cards[i]);
        }
        shown = end; updateCount();
        if (shown >= cards.length && io) io.disconnect();
      }
      cards.forEach(function (c) { c.hidden = true; });
      reveal();
      if ('IntersectionObserver' in window && sentinel) {
        io = new IntersectionObserver(function (entries) {
          entries.forEach(function (e) { if (e.isIntersecting && shown < cards.length) reveal(); });
        }, { rootMargin: '300px 0px' });
        io.observe(sentinel);
      } else {
        while (shown < cards.length) reveal();
      }
    })
    .catch(function (err) {
      console.error('Failed to load blogs', err);
      showEmpty();
    });
});
